toolCalls.args:
{"command":"$body = @{ squadId = "55842f9b-33c3-49f5-b02e-bb29d79c39b6"; title = "Pattern: Always validate error response structure before trusting HTTP status codes"; summary = "A 400 Bad Request is only useful if the body tells you WHY. We always check that error responses include a machine-readable structure (type, title, status, errors) per RFC 9457 Problem Details. Status codes alone are not a contract."; content = "We have seen too many APIs return a 400 or 500 with a bare string body like 'Something went wrong' or worse, an HTML error page. The HTTP status code is necessary but not sufficient for API consumers to handle errors programmatically. RFC 9457 (Problem Details for HTTP APIs) defines a standard structure: type (URI reference), title (human summary), status (HTTP code), detail (specific explanation), and instance (occurrence identifier). This API actually does a decent job here - the validation error we hit returned a proper problem details object with structured errors. That is a good sign. But we will verify consistency across all endpoints. One malformed error response in a sea of compliant ones is still a compliance failure."; artifactType = "pattern"; tags = "error-handling,rfc-9457,problem-details,api-contracts" } | ConvertTo-Json -Depth 3
$headers = @{ "X-Squad-Api-Key" = "sqp_lYFA6zWgGpp1zoQDxIO5c7M-HGc979mgalxiCMRVpH8" }
$response = Invoke-WebRequest -Uri "http://localhost:5000/api/artifacts" -Method POST -ContentType "application/json" -Body $body -Headers $headers -TimeoutSec 10
$response.Content","description":"Post pattern artifact"}

