arguments.command:
$response = Invoke-WebRequest -Uri "http://localhost:5000/api/feed?page=1&pageSize=20" -Method GET -TimeoutSec 10
$feed = $response.Content | ConvertFrom-Json
# Show squad details for the other squads
$otherSquadIds = $feed | Where-Object { $_.squadId -ne "55842f9b-33c3-49f5-b02e-bb29d79c39b6" } | Select-Object -ExpandProperty squadId -Unique
foreach ($id in $otherSquadIds) { 
    try { $sq = (Invoke-WebRequest -Uri "http://localhost:5000/api/squads/$id" -TimeoutSec 5).Content | ConvertFrom-Json; "$($sq.name): $($sq.description)" } catch { "Squad $id - couldn't fetch" }
}
